def _douyin_base_params(aweme_id: str, ms_token: str | None) -> dict:
    params = {
        "device_platform": "webapp",
        "aid": "6383",
        "channel": "channel_pc_web",
        "pc_client_type": 1,
        "version_code": "290100",
        "version_name": "29.1.0",
        "cookie_enabled": "true",
        "screen_width": 1920,
        "screen_height": 1080,
        "browser_language": "zh-CN",
        "browser_platform": "Win32",
        "browser_name": "Chrome",
        "browser_version": "130.0.0.0",
        "browser_online": "true",
        "engine_name": "Blink",
        "engine_version": "130.0.0.0",
        "os_name": "Windows",
        "os_version": "10",
        "cpu_core_num": 12,
        "device_memory": 8,
        "platform": "PC",
        "downlink": "10",
        "effective_type": "4g",
        "from_user_page": "1",
        "locate_query": "false",
        "need_time_list": "1",
        "pc_libra_divert": "Windows",
        "publish_video_strategy_type": "2",
        "round_trip_time": "0",
        "show_live_replay_strategy": "1",
        "time_list_query": "0",
        "whale_cut_token": "",
        "update_version_code": "170400",
        "aweme_id": aweme_id,
    }
    if ms_token:
        params["msToken"] = ms_token
    return params


def _bootstrap_douyin_cookies() -> dict[str, str]:
    """Create fresh Douyin visitor cookies.

    This follows BiliNote's DouyinDownloader endpoints (ttwid registration +
    mssdk msToken) and then attaches the generated cookies to the detail
    request.  The latter step is required now: the detail API returns an
    empty body when the cookies are generated but never sent.
    """
    cookies: dict[str, str] = {}
    headers = {
        "User-Agent": USER_AGENT,
        "Accept-Language": "zh-CN,zh;q=0.9",
        "Referer": "https://www.douyin.com/",
    }
    with httpx.Client(
        headers=headers,
        follow_redirects=True,
        timeout=httpx.Timeout(20.0),
        **_client_proxy_kwargs(),
    ) as client:
        try:
            client.get("https://www.douyin.com/")
        except httpx.HTTPError as e:
            logger.warning("获取抖音首页 Cookie 失败: %s", e)

        try:
            client.post(
                DOUYIN_TTWID_URL,
                content=DOUYIN_TTWID_DATA,
                headers={"Content-Type": "application/json"},
            )
        except httpx.HTTPError as e:
            logger.warning("注册抖音 ttwid 失败: %s", e)

        try:
            payload = json.dumps(
                {
                    "magic": 538969122,
                    "version": 1,
                    "dataType": 8,
                    "strData": DOUYIN_MS_TOKEN_STR_DATA,
                    "tspFromClient": int(time.time() * 1000),
                }
            )
            response = client.post(
                DOUYIN_MS_TOKEN_URL,
                content=payload,
                headers={"Content-Type": "application/json"},
            )
            for cookie in response.cookies.jar:
                if cookie.name == "msToken":
                    cookies[cookie.name] = cookie.value
        except httpx.HTTPError as e:
            logger.warning("获取抖音 msToken 失败: %s", e)

        for cookie in client.cookies.jar:
            if cookie.name in ("__ac_nonce", "ttwid"):
                cookies[cookie.name] = cookie.value

    return cookies


def _douyin_cookie_string() -> tuple[dict[str, str], str]:
    cookies = _bootstrap_douyin_cookies()
    configured = _platform_env("douyin", "DOUYIN_COOKIE")
    if configured:
        cookies.update(_parse_cookie_string(configured))
    cookie_string = "; ".join(f"{name}={value}" for name, value in cookies.items())
    return cookies, cookie_string


def _fetch_douyin_detail(video_id: str, cookie_string: str) -> dict:
    params = _douyin_base_params(
        video_id, _parse_cookie_string(cookie_string).get("msToken")
    )
    url = "https://www.douyin.com/aweme/v1/web/aweme/detail/?" + urlencode(params)
    headers = {
        "User-Agent": USER_AGENT,
        "Accept-Language": "zh-CN,zh;q=0.9",
        "Referer": "https://www.douyin.com/",
        "Cookie": cookie_string,
    }
    with httpx.Client(
        follow_redirects=True,
        timeout=httpx.Timeout(20.0),
        **_client_proxy_kwargs(),
    ) as client:
        response = client.get(url, headers=headers)
    if response.status_code != 200:
        raise DownloadError(f"抖音接口返回 HTTP {response.status_code}")
    if not response.content.strip():
        raise DownloadError("抖音接口返回空响应（可能需要设置 DOUYIN_COOKIE）")
    try:
        data = response.json()
    except json.JSONDecodeError as e:
        raise DownloadError(f"抖音接口返回非 JSON 响应：{response.text[:120]!r}") from e
    if not data.get("aweme_detail"):
        reason = (data.get("filter_detail") or {}).get("filter_reason", "")
        raise DownloadError(
            f"抖音未返回视频详情（{reason or '可能已删除或不可访问'}）"
        )
    return data


def _download_douyin(url: str, output_dir: Path) -> DownloadedVideo:
    canonical_url = canonical_douyin_url(url, proxy=_proxy_url())
    video_id = extract_video_id(canonical_url, "douyin") or ""
    existing = _existing_file(output_dir, video_id)
    if existing:
        print(f"⏭️  已下载过抖音视频：{existing.name}")
        return DownloadedVideo(
            video_path=existing,
            source_url=url,
            platform="douyin",
            video_id=video_id,
        )

    cookies, cookie_string = _douyin_cookie_string()

    # Preferred path: BiliNote's aweme-detail API + direct media URL.
    try:
        data = _fetch_douyin_detail(video_id, cookie_string)
        aweme = data["aweme_detail"]
        video = aweme.get("video") or {}
        urls = []
        for key in ("download_addr", "play_addr"):
            urls.extend(video.get(key, {}).get("url_list") or [])
        media_url = urls[0] if urls else None
        if media_url:
            target = output_dir / f"{video_id}.mp4"
            _stream_download(
                media_url,
                target,
                headers={
                    "User-Agent": USER_AGENT,
                    "Referer": "https://www.douyin.com/",
                },
            )
            return DownloadedVideo(
                video_path=target,
                source_url=url,
                platform="douyin",
                video_id=video_id,
                title=str(aweme.get("desc") or aweme.get("item_title") or ""),
                duration=_duration_seconds(video.get("duration")),
                thumbnail=(video.get("cover") or {}).get("url_list", [None])[0],
            )
    except DownloadError as e:
        logger.warning("抖音 API 直连下载失败，回退 yt-dlp：%s", e)

    # Fallback: yt-dlp with the freshly generated visitor cookie file.
    cleanup_paths: list[Path] = []
    cookiefile: Path | None = None
    if cookies:
        cookiefile = _write_netscape_cookie_file(cookies, ".douyin.com")
        cleanup_paths.append(cookiefile)
    try:
        return _download_with_ytdlp(
            canonical_url, "douyin", output_dir, cookiefile=cookiefile
        )
    finally:
        _cleanup(cleanup_paths)


def _stream_download(url: str, target: Path, headers: dict | None = None) -> None:
    """Download a media URL to ``target`` atomically-ish (tmp + rename)."""
    tmp = target.with_name(f".{target.name}.part")
    target.parent.mkdir(parents=True, exist_ok=True)
    merged = {"User-Agent": USER_AGENT}
    if headers:
        merged.update(headers)
    try:
        with httpx.Client(
            headers=merged,
            follow_redirects=True,
            timeout=httpx.Timeout(30.0, connect=30.0, read=None, write=60.0, pool=20.0),
            **_client_proxy_kwargs(),
        ) as client, client.stream("GET", url) as response:
            if response.status_code != 200:
                raise DownloadError(f"媒体下载失败：HTTP {response.status_code}")
            with tmp.open("wb") as f:
                for chunk in response.iter_bytes(1024 * 1024):
                    f.write(chunk)
        tmp.replace(target)
    except DownloadError:
        raise
    except httpx.HTTPError as e:
        raise DownloadError(f"媒体下载失败：{e}") from e
    finally:
        tmp.unlink(missing_ok=True)


# ---------------------------------------------------------------------------
# Kuaishou
# ---------------------------------------------------------------------------


def _kuaishou_cookie_string(client: httpx.Client) -> str:
    configured = _platform_env("kuaishou", "KUAISHOU_COOKIE")
    if configured:
        return configured

    # BiliNote's KuaiShou helper asks the homepage for visitor cookies.
    client.get("https://www.kuaishou.com/")
    pairs: list[str] = []
    for cookie in client.cookies.jar:
        domain = cookie.domain or ""
        if domain.endswith(("kuaishou.com", "chenzhongtech.com")):
            pairs.append(f"{cookie.name}={cookie.value}")
    return "; ".join(pairs)


def _kuaishou_video_url(photo: dict) -> str | None:
    url = photo.get("photoUrl")
    if url:
        return url
    for adaptation in (photo.get("manifest") or {}).get("adaptationSet") or []:
        for representation in adaptation.get("representation") or []:
            for key in ("url", "backupUrl"):
                url = representation.get(key)
                if url:
                    return url
    return None


def _download_kuaishou(url: str, output_dir: Path) -> DownloadedVideo:
    headers = KUAISHOU_HEADERS.copy()
    client = httpx.Client(
        headers=headers,
        follow_redirects=True,
        timeout=httpx.Timeout(20.0),
        **_client_proxy_kwargs(),
    )
    try:
        resolved = str(client.get(url).url)
        photo_id = extract_video_id(resolved, "kuaishou") or ""
        if not photo_id:
            match = re.search(r"short-video/(\w+)", resolved)
            photo_id = match.group(1) if match else ""

        existing = _existing_file(output_dir, photo_id)
        if existing:
            print(f"⏭️  已下载过快手视频：{existing.name}")
            return DownloadedVideo(
                video_path=existing,
                source_url=url,
                platform="kuaishou",
                video_id=photo_id,
            )

        if not photo_id:
            raise DownloadError(f"无法从快手链接解析视频 ID：{resolved}")

        cookie_string = _kuaishou_cookie_string(client)
        client.headers["Cookie"] = cookie_string
        client.headers["Referer"] = resolved

        payload = {
            "operationName": "visionVideoDetail",
            "variables": {"photoId": photo_id, "page": "detail"},
            "query": KUAISHOU_GRAPHQL_QUERY,
        }
        response = client.post(KUAISHOU_GRAPHQL_URL, json=payload)
        if response.status_code != 200:
            raise DownloadError(
                f"快手接口返回 HTTP {response.status_code}：{response.text[:120]}"
            )
        try:
            data = response.json()
        except json.JSONDecodeError as e:
            raise DownloadError(
                f"快手接口返回非 JSON 响应：{response.text[:120]!r}"
            ) from e

        data_payload = data.get("data") or {}
        result_code = data.get("result") or data_payload.get("result")
        if result_code or data_payload.get("captcha"):
            raise DownloadError(
                "快手接口触发风控验证。请使用浏览器登录快手后，把浏览器里的完整 "
                "Cookie 配置到 .env 的 KUAISHOU_COOKIE 后重试。"
            )

        detail = data_payload.get("visionVideoDetail") or {}
        photo = detail.get("photo") or {}
        media_url = _kuaishou_video_url(photo)
        if not photo.get("id") or not media_url:
            raise DownloadError(
                "快手接口未返回可下载的视频地址（可能需要设置 KUAISHOU_COOKIE）"
            )

        target = output_dir / f"{photo['id']}.mp4"
        _stream_download(
            media_url,
            target,
            headers={"Referer": resolved},
        )
        return DownloadedVideo(
            video_path=target,
            source_url=url,
            platform="kuaishou",
            video_id=str(photo["id"]),
            title=str(photo.get("caption") or ""),
            duration=_duration_seconds(photo.get("duration")),
            thumbnail=photo.get("coverUrl"),
        )
    finally:
        client.close()


