# public API
# ---------------------------------------------------------------------------

_DOWNLOADERS: dict[str, Callable[[str, Path], DownloadedVideo]] = {
    "youtube": _download_youtube,
    "bilibili": _download_bilibili,
    "douyin": _download_douyin,
    "kuaishou": _download_kuaishou,
}


def download_video(source: str, output_dir: str | Path | None = None) -> DownloadedVideo:
    """Download an online video and return its local path.

    ``source`` may be a plain URL or a complete share message containing a
    URL (common for Douyin / Kuaishou).
    """
    url = extract_url(source)
    if not url:
        raise DownloadError(f"未在输入中找到视频链接：{source!r}")

    platform = detect_platform(url)
    if not platform:
        raise DownloadError(
            f"暂不支持该视频平台或链接格式无效：{url}（支持 YouTube / Bilibili / 抖音 / 快手）"
        )

    directory = Path(output_dir).expanduser() if output_dir else _download_dir()
    directory.mkdir(parents=True, exist_ok=True)

    print(f"⬇️  正在下载 {platform} 视频：{url}")
    try:
        return _DOWNLOADERS[platform](url, directory)
    except DownloadError:
        raise
    except Exception as e:
        raise DownloadError(f"{platform} 视频下载失败：{e}") from e


